 public static void install(Activity a){if(installed!=null)installed.dispose();PANearbyBoards next=new PANearbyBoards(a);installed=next;a.getApplication().registerActivityLifecycleCallbacks(next);next.main.post(()->next.locate(0));}
 private PANearbyBoards(Activity a){activity=a;manualId=a.getSharedPreferences("pa2_boards",0).getString("manual_stop","");mineTab="mine".equals(a.getSharedPreferences("pa2_boards",0).getString("boards_tab","gps"));try{JSONArray saved=new JSONArray(a.getSharedPreferences("pa2_boards",0).getString("saved_stops","[]"));for(int i=0;i<saved.length();i++){JSONObject s=saved.optJSONObject(i);if(s!=null&&!s.optString("id").isEmpty())savedStops.put(s.getString("id"),s);}}catch(JSONException ignored){}}
 private int dp(float x){return Math.round(x*activity.getResources().getDisplayMetrics().density);}
