  subtitle=text(mineTab?"Twoje zapisane przystanki · bez GPS":"Najbliższe stanowiska według GPS",12,MUTED,false);subtitle.setPadding(0,dp(8),0,dp(8));panel.addView(subtitle);savedArea=col();savedArea.setTag("pa-my-stops");panel.addView(savedArea,new LinearLayout.LayoutParams(-1,-2));content=col();panel.addView(content,new LinearLayout.LayoutParams(-1,-2));
  gpsActions=row();LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(0,-2,1);ap.rightMargin=dp(5);gpsActions.addView(button("Wybierz przystanek",this::manualPicker),ap);gpsActions.addView(button("Odśwież GPS",this::useGPS),new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams alp=new LinearLayout.LayoutParams(-1,-2);alp.topMargin=dp(8);panel.addView(gpsActions,alp);renderTabs();renderSaved();
  int at=parent.indexOfChild(current);ViewGroup.LayoutParams params=current.getLayoutParams();parent.removeViewAt(at);parent.addView(panel,at,params);panel.setAlpha(0);panel.animate().alpha(1).setDuration(220).start();message("Wczytuję lokalny rozkład…");main.removeCallbacks(refresh);main.removeCallbacks(tick);main.post(refresh);main.post(tick);
